import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('ProfilePage', () {
    final MockSettingsRepository mockSettingsRepository = MockSettingsRepository();

    late StreamController<AppThemeMode> themeModeController;

    setUp(() {
      themeModeController = StreamController<AppThemeMode>.broadcast();
      when(mockSettingsRepository.themeModeStream).thenAnswer((_) => themeModeController.stream);
      when(mockSettingsRepository.readThemeMode()).thenReturn(AppThemeMode.light);
    });

    tearDown(() => themeModeController.close());

    Future<void> pumpProfilePage(WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<SettingsRepository>.value(value: mockSettingsRepository),
          ],
          child: const ProfilePage(),
        ),
      );

      await tester.pump();
    }

    testWidgets('should display theme mode read synchronously on init', (WidgetTester tester) async {
      await pumpProfilePage(tester);

      expect(find.text('Светлая'), findsOneWidget);
    });

    testWidgets('should update displayed theme mode when settings stream emits', (WidgetTester tester) async {
